window.showScreen=function(id){['login-screen','main-menu-screen','room-browser-screen','shop-screen','lobby-screen','game-screen','hangar-screen','upgrader-screen'].forEach(i=>{let el=document.getElementById(i);if(el){el.classList.add('hidden');el.classList.remove('flex');}});let s=document.getElementById(id);if(s){s.classList.remove('hidden');if(id!=='game-screen')s.classList.add('flex');}if(typeof playSound==='function')playSound('ui_click');if(id==='hangar-screen'){if(typeof startHangarPreview==='function')startHangarPreview();}else{if(typeof stopHangarPreview==='function')stopHangarPreview();}};
