window.openAdvent=function(){if(typeof playSound==='function')playSound('ui_click');document.getElementById('advent-modal').classList.remove('hidden');socket.emit('getAdventState');renderAdvent();};
window.renderAdvent=function(){let grid=document.getElementById('advent-grid');if(!grid)return;grid.innerHTML='';let cD=window.adventDay||0,claims=myAdventClaims||[];const cnt=document.getElementById('advent-counter');if(cnt)cnt.innerText=claims.length;for(let d=3;d<=31;d++){let state='',content='',bg='bg-slate-800 border-slate-700',cursor='cursor-not-allowed opacity-50',onclick='';if(claims.includes(d)){state='ЗАБРАНО';bg='bg-emerald-900/50 border-emerald-500 text-emerald-400';content='✔️';}else if(d<cD){state='ПРОПУЩЕНО';bg='bg-red-900/30 border-red-800 text-red-500';content='❌';}else if(d===cD){state='ЗАБРАТИ';bg='bg-orange-600 border-orange-400 text-white animate-pulse shadow-[0_0_15px_#ea580c]';cursor='cursor-pointer hover:bg-orange-500';content=d===31?'🎁':`💵 ${20+(d-3)*5}`;onclick=`onclick="claimAdventDay()"`}else{state='ЗАКРИТО';bg='bg-slate-900 border-slate-700 text-slate-500';content='🔒';}if(d===31&&state!=='ЗАБРАНО'&&state!=='ЗАБРАТИ')content='🎃';grid.innerHTML+=`<div class="flex flex-col items-center justify-center p-2 rounded-xl border ${bg} ${cursor} transition h-20 relative overflow-hidden group" ${onclick}><span class="text-[10px] font-bold mb-1 opacity-70">${d}.10</span><span class="text-xl font-russo z-10 group-hover:scale-110 transition">${content}</span></div>`;}};
window.claimAdventDay=function(){socket.emit('claimAdvent');};
let _advLast=0;setInterval(()=>{let nowS=Date.now()+(window.adventOffset||0),timerEl=document.getElementById('hw-timer'),diff=(window.adventEnd||0)-nowS;if(Date.now()-_advLast>120000){_advLast=Date.now();socket.emit('getAdventState');}if(window.adventEnd&&diff>0&&timerEl){let d=Math.floor(diff/(1000*60*60*24)),h=Math.floor((diff/(1000*60*60))%24),m=Math.floor((diff/1000/60)%60),s=Math.floor((diff/1000)%60);timerEl.innerText=`${d}Д ${h.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}:${s.toString().padStart(2,'0')}`;}else if(timerEl&&window.adventEnd){timerEl.innerText="ХЕЛОУІН НАСТАВ!";}},1000);

window.renderShop=function(){const c=document.getElementById('shop-cases-container');if(!c)return;c.innerHTML='';Object.keys(CASES).forEach(k=>{let cs=CASES[k];c.innerHTML+=`<div class="glass-panel p-2 lg:p-6 rounded-xl lg:rounded-[2rem] border flex flex-col items-center relative group shadow-lg" style="border-color:${cs.color}50"><button onclick="event.stopPropagation(); openCaseInfo(${k})" class="absolute top-2 right-2 lg:top-4 lg:right-4 w-7 h-7 lg:w-10 lg:h-10 rounded-full font-russo text-[10px] lg:text-lg border flex items-center justify-center z-30 cursor-pointer hover:scale-110 transition shadow-md" style="background-color:${cs.color}30;color:${cs.color};border-color:${cs.color}">i</button><div class="text-5xl lg:text-7xl drop-shadow-xl z-10 group-hover:scale-110 transition-transform mb-2 lg:mb-4">${cs.icon}</div><div class="text-center z-10 w-full"><h3 class="text-[10px] sm:text-sm lg:text-xl font-russo tracking-widest uppercase truncate px-1 mb-1" style="color:${cs.color}">${cs.name}</h3><p class="text-[6px] lg:text-[9px] text-slate-400 font-bold uppercase tracking-wider leading-tight hidden sm:block">Звич: ${cs.drop.c}% | Рідк: ${cs.drop.r}%<br>Епік: ${cs.drop.e}% | Лег: ${cs.drop.l}%</p></div><button onclick="buyShopCase(${k}, ${cs.price})" class="w-full mt-2 lg:mt-4 text-white font-bold py-1.5 lg:py-3 rounded-lg lg:rounded-xl text-[10px] sm:text-sm lg:text-lg font-russo uppercase tracking-widest shadow-md transition hover:scale-105 cursor-pointer z-20" style="background-color:${cs.color}">💵 ${cs.price}</button></div>`;});};
window.openCaseInfo=function(caseId){if(typeof playSound==='function')playSound('ui_click');const modal=document.getElementById('case-info-modal'),grid=document.getElementById('case-info-grid'),title=document.getElementById('case-info-title');if(!grid||!modal)return;grid.innerHTML='';let cs=CASES[caseId];title.innerText=`КЕЙС "${cs.name}"`;title.style.color=cs.color;let pool=Object.keys(MODULES);if(cs.pool==='cannon')pool=Object.keys(MODULES).filter(m=>MODULES[m].type==='cannon');else if(cs.pool==='turret')pool=Object.keys(MODULES).filter(m=>MODULES[m].type==='turret');else if(cs.pool==='hull')pool=Object.keys(MODULES).filter(m=>MODULES[m].type==='hull');else if(cs.pool==='tracks')pool=Object.keys(MODULES).filter(m=>MODULES[m].type==='tracks');else if(Array.isArray(cs.pool))pool=cs.pool;else if(cs.drop&&cs.drop.l===100)pool=Object.keys(MODULES).filter(m=>MODULES[m].rarity==='legendary');const sR=['legendary','epic','rare','common'];sR.forEach(rar=>{let filtered=pool.filter(m=>MODULES[m].rarity===rar);if(filtered.length===0)return;let chance=cs.drop[rar.charAt(0)];if(chance===0)return;grid.innerHTML+=`<div class="col-span-full mt-4 mb-2"><span class="text-[10px] md:text-sm font-bold uppercase tracking-widest px-3 py-1 rounded" style="background-color: ${RARITY[rar].color}40; color: ${RARITY[rar].color}">${RARITY[rar].name} (${chance}%)</span></div>`;let sG=`<div class="grid grid-cols-2 sm:grid-cols-3 gap-2 md:gap-3 mb-4 md:mb-6">`;filtered.forEach(modId=>{let mod=MODULES[modId];let iS=SVG_ICONS[mod.type](RARITY[mod.rarity].color);sG+=`<div class="flex items-center gap-2 md:gap-3 bg-slate-800/50 p-2 md:p-3 rounded-xl border border-slate-700"><div class="w-8 h-8 md:w-10 md:h-10 p-1.5 md:p-2 flex-shrink-0 flex items-center justify-center rounded-lg bg-slate-900 border" style="border-color:${RARITY[mod.rarity].color}">${iS}</div><div class="overflow-hidden"><p class="text-[10px] md:text-xs text-white font-bold truncate">${mod.name}</p><p class="text-[8px] md:text-[9px] uppercase font-bold truncate" style="color:${RARITY[mod.rarity].color}">${CAT_NAMES[mod.type]}</p></div></div>`;});sG+=`</div>`;grid.innerHTML+=sG;});modal.classList.remove('hidden');};
window.buyShopCase=function(caseId,price){if(myBucks>=price){if(myInventory.length>=30)return alert('Звільніть місце в Інвентарі!');document.getElementById('case-confirm-modal').classList.remove('hidden');document.getElementById('confirm-case-btn').onclick=()=>{if(typeof playSound==='function')playSound('ui_buy');document.getElementById('case-confirm-modal').classList.add('hidden');socket.emit('buyCase',caseId);};}else alert('Недостатньо баксів!');};
const ccb=document.getElementById('cancel-case-btn');if(ccb)ccb.onclick=()=>{if(typeof playSound==='function')playSound('ui_click');document.getElementById('case-confirm-modal').classList.add('hidden');};
const crb=document.getElementById('close-reward-btn');if(crb)crb.onclick=()=>{if(typeof playSound==='function')playSound('ui_click');document.getElementById('reward-modal').classList.add('hidden');if(!document.getElementById('hangar-screen').classList.contains('hidden'))if(typeof renderHangar==='function')renderHangar();};
window.renderRoomsList=function(rooms){const list=document.getElementById('rooms-list');if(!list)return;list.innerHTML='';if(rooms.length===0){list.innerHTML='<div class="text-center text-slate-500 py-10 font-bold tracking-widest uppercase text-xs md:text-sm">Немає активних сесій</div>';return;}rooms.forEach(r=>{let isFull=r.playersCount>=r.maxPlayers,inProgress=r.status==='playing',btnHtml='';if(inProgress)btnHtml='<button disabled class="bg-slate-700 text-slate-500 px-3 md:px-4 py-1.5 md:py-2 rounded font-bold uppercase text-[9px] md:text-xs">В ГРІ</button>';else if(isFull)btnHtml='<button disabled class="bg-red-900/50 text-red-500 px-3 md:px-4 py-1.5 md:py-2 rounded font-bold uppercase text-[9px] md:text-xs border border-red-500/30">ПОВНА</button>';else btnHtml=`<button onclick="joinRoomBtn('${r.id}')" class="bg-blue-600 hover:bg-blue-500 text-white px-3 md:px-4 py-1.5 md:py-2 rounded font-bold uppercase text-[9px] md:text-xs transition shadow-[0_0_10px_rgba(37,99,235,0.4)]">ПІД'ЄДНАТИСЬ</button>`;const modeEmoji=r.mode==='survival'?'🧟':r.mode==='prophunt'?'📦':r.mode==='team_deathmatch'?'🤝':'⚔',modeName=r.mode==='survival'?'ВИЖИВАННЯ':r.mode==='prophunt'?'ХОВАНКИ':r.mode==='team_deathmatch'?'КОМАНДНИЙ':'ДЕТМАТЧ';list.innerHTML+=`<div class="grid grid-cols-4 md:grid-cols-5 gap-2 md:gap-4 items-center p-3 md:p-4 bg-slate-800/50 hover:bg-slate-800 rounded-xl border border-slate-700 transition"><div class="col-span-2 flex flex-col"><span class="font-bold text-white text-[10px] md:text-sm truncate">${r.hostName}</span><span class="text-[8px] md:text-[10px] text-slate-500 font-mono hidden sm:block">${r.id}</span></div><div class="text-[9px] md:text-sm font-bold text-slate-300 uppercase hidden md:block">${modeEmoji} ${modeName}</div><div class="text-[9px] md:text-sm text-slate-300 uppercase truncate">${r.map}</div><div class="flex justify-between items-center"><span class="font-russo text-xs md:text-base ${isFull?'text-red-400':'text-blue-400'} mr-2">${r.playersCount}/${r.maxPlayers}</span>${btnHtml}</div></div>`;});};
window.joinRoomBtn=function(roomId){if(typeof playSound==='function')playSound('ui_click');socket.emit('joinRoom',roomId);};
let createConfig={mode:'deathmatch',map:'epic_map',maxPlayers:6,winScore:50,tdmTeams:2,tdmTime:180,tdmScore:20,tdmAutoBalance:true};
window.drawMapPreview=function(mapName){const cvs=document.getElementById('map-preview-canvas');if(!cvs)return;const ctx=cvs.getContext('2d'),rect=cvs.parentElement.getBoundingClientRect();cvs.width=rect.width;cvs.height=rect.height;const m=MAP_DATA[mapName];if(!m)return;const tEl=document.getElementById('preview-map-name');if(tEl)tEl.innerText=mapName==='epic_map'?'🌐 EPIC MAP':'🔥 ДЕЗМАТЧ';ctx.clearRect(0,0,cvs.width,cvs.height);const sc=Math.min(cvs.width/m.size,cvs.height/m.size)*0.95;ctx.save();ctx.translate(cvs.width/2-(m.size*sc)/2,cvs.height/2-(m.size*sc)/2);ctx.scale(sc,sc);ctx.fillStyle=m.bg||'#020617';ctx.fillRect(0,0,m.size,m.size);ctx.strokeStyle=m.grid||'#1e293b';ctx.lineWidth=2;for(let i=0;i<=m.size;i+=50){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,m.size);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(m.size,i);ctx.stroke();}m.solids.forEach(o=>{ctx.save();if(o.type==='line'){ctx.strokeStyle=o.color;ctx.lineWidth=o.width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(o.points[0].x,o.points[0].y);for(let i=1;i<o.points.length;i++)ctx.lineTo(o.points[i].x,o.points[i].y);ctx.stroke();}else if(o.type.includes('water')){ctx.fillStyle='#0369a1';if(o.type==='water_curve'){ctx.beginPath();ctx.roundRect(o.x,o.y,o.w,o.h,Math.min(o.w,o.h)/2);ctx.fill();}else ctx.fillRect(o.x,o.y,o.w,o.h);}else if(o.type==='shape_triangle'){ctx.fillStyle=o.color||'#333';ctx.beginPath();ctx.moveTo(o.x+o.w/2,o.y);ctx.lineTo(o.x+o.w,o.y+o.h);ctx.lineTo(o.x,o.y+o.h);ctx.fill();}else if(o.type==='shape_rhombus'){ctx.fillStyle=o.color||'#333';ctx.beginPath();ctx.moveTo(o.x+o.w/2,o.y);ctx.lineTo(o.x+o.w,o.y+o.h/2);ctx.lineTo(o.x+o.w/2,o.y+o.h);ctx.lineTo(o.x,o.y+o.h/2);ctx.fill();}else if(o.type==='wall_square'){ctx.fillStyle=o.color||'#1e293b';ctx.fillRect(o.x,o.y,o.w,o.h);}else if(o.type==='tree'){ctx.beginPath();ctx.arc(o.x,o.y,o.r||30,0,Math.PI*2);ctx.fillStyle='#0c0a09';ctx.fill();ctx.fillStyle='rgba(22, 163, 74, 0.4)';ctx.beginPath();ctx.arc(o.x+5,o.y+5,Math.max(5,(o.r||30)-10),0,Math.PI*2);ctx.fill();}else if(o.type.includes('neon')){ctx.strokeStyle=o.color;ctx.lineWidth=10;if(o.type==='neon_circle'){ctx.beginPath();ctx.arc(o.x+o.w/2,o.y+o.h/2,Math.min(o.w,o.h)/2,0,Math.PI*2);ctx.stroke();}else ctx.strokeRect(o.x,o.y,o.w,o.h);ctx.fillStyle=o.color;ctx.globalAlpha=0.4;ctx.fillRect(o.x,o.y,o.w,o.h);}else if(o.type.includes('spawn')){ctx.beginPath();ctx.arc(o.x,o.y,25,0,Math.PI*2);ctx.fillStyle=o.type==='spawn_player'?'#3b82f6':o.type==='spawn_zombie'?'#22c55e':'#eab308';ctx.fill();}else if(o.type.includes('prop_')){if(typeof drPrp==='function')drPrp(ctx,o,0);}ctx.restore();});ctx.restore();};
document.getElementById('open-create-room-btn').onclick=()=>{if(typeof playSound==='function')playSound('ui_click');document.getElementById('create-room-modal').classList.remove('hidden');setTimeout(()=>drawMapPreview(createConfig.map),50);};
