document.querySelectorAll('.create-mode-select').forEach(btn=>{btn.onclick=()=>{if(typeof playSound==='function')playSound('ui_click');document.querySelectorAll('.create-mode-select').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');createConfig.mode=btn.dataset.mode;const sW=document.getElementById('create-score-wrap');if(sW)sW.style.display=createConfig.mode==='deathmatch'?'block':'none';const phW=document.getElementById('create-prophunt-wrap');if(phW)phW.style.display=createConfig.mode==='prophunt'?'block':'none';const tdmW=document.getElementById('create-tdm-wrap');if(tdmW)tdmW.style.display=createConfig.mode==='team_deathmatch'?'block':'none';};});
