const maxP=document.getElementById('create-max-players');if(maxP)maxP.oninput=(e)=>{createConfig.maxPlayers=e.target.value;const v=document.getElementById('max-players-val');if(v)v.innerText=e.target.value;};
document.getElementById('confirm-create-btn').onclick=()=>{if(typeof playSound==='function')playSound('ui_click');const ws=document.getElementById('create-win-score');if(ws)createConfig.winScore=ws.value;if(createConfig.mode==='prophunt'){const hT=document.getElementById('create-hide-time'),sT=document.getElementById('create-seek-time'),hC=document.getElementById('create-hunter-count');if(hT)createConfig.hideTime=Math.max(30,Math.min(200,parseInt(hT.value)));if(sT)createConfig.seekTime=Math.max(120,Math.min(600,parseInt(sT.value)));if(hC)createConfig.hunterCount=Math.max(1,parseInt(hC.value));}if(createConfig.mode==='team_deathmatch'){const tt=document.getElementById('create-tdm-teams'),tm=document.getElementById('create-tdm-time'),ts=document.getElementById('create-tdm-score'),ta=document.getElementById('create-tdm-autobalance');if(tt)createConfig.tdmTeams=parseInt(tt.value);if(tm)createConfig.tdmTime=parseInt(tm.value);if(ts)createConfig.tdmScore=parseInt(ts.value);if(ta)createConfig.tdmAutoBalance=ta.checked;}document.getElementById('create-room-modal').classList.add('hidden');socket.emit('createRoom',createConfig);};
let dragSource=null;window.dragStartInv=function(e,modId,index){dragSource={type:'inv',index:index,id:modId};e.dataTransfer.setData('text/plain',modId);};window.dragStartEq=function(e,modId,slotType){dragSource={type:'eq',slotType:slotType,id:modId};e.dataTransfer.setData('text/plain',modId);};window.allowDrop=function(e){e.preventDefault();};
window.dropInv=function(e,targetIndex){e.preventDefault();if(!dragSource)return;if(dragSource.type==='inv'){if(dragSource.index!==targetIndex){let item=myInventory.splice(dragSource.index,1)[0];let target=targetIndex>myInventory.length?myInventory.length:targetIndex;myInventory.splice(target,0,item);if(typeof renderHangar==='function')renderHangar();socket.emit('reorderInventory',myInventory);}}else if(dragSource.type==='eq'){socket.emit('unequipModule',{type:dragSource.slotType});}dragSource=null;};
window.dropEq=function(e,slotType){e.preventDefault();if(!dragSource)return;if(dragSource.type==='inv'){let mod=MODULES[dragSource.id];if(mod&&mod.type===slotType){if(typeof playSound==='function')playSound('powerup');socket.emit('equipModule',{id:dragSource.id,type:slotType});}else{if(typeof playSound==='function')playSound('ui_click');}}dragSource=null;};

window.renderHangar=function(){const pn=document.getElementById('hangar-player-name');if(pn)pn.innerText=myName;if(document.getElementById('stat-kills'))document.getElementById('stat-kills').innerText=myStats.kills||0;if(document.getElementById('stat-matches'))document.getElementById('stat-matches').innerText=myStats.matches||0;let totalDmg=1.0,totalRange=1.0,totalCd=1.0,totalHp=1.0,totalSpeed=1.0,totalRot=1.0;const eqHtml=[];const types=[{k:'cannon',n:'Дуло'},{k:'turret',n:'Башта'},{k:'hull',n:'Корпус'},{k:'tracks',n:'Гусениці'}];types.forEach(t=>{let modId=myEquipped[t.k];if(modId&&MODULES[modId]){let m=MODULES[modId];if(m.stats.dmg)totalDmg*=m.stats.dmg;if(m.stats.range)totalRange*=m.stats.range;if(m.stats.cd)totalCd*=m.stats.cd;if(m.stats.hp)totalHp*=m.stats.hp;if(m.stats.speed)totalSpeed*=m.stats.speed;if(m.stats.rotSpeed)totalRot*=m.stats.rotSpeed;let iconSvg=SVG_ICONS[t.k](RARITY[m.rarity].color);eqHtml.push(`<div class="flex items-center gap-2 md:gap-3 bg-slate-800/50 p-2 rounded-xl border border-slate-700 cursor-pointer hover:bg-slate-700/50 transition relative overflow-hidden group" draggable="true" ondragstart="dragStartEq(event, '${modId}', '${t.k}')" ondragover="allowDrop(event)" ondrop="dropEq(event, '${t.k}')" onclick="openCtxMenu(event, '${modId}', 'eq', '${t.k}')"><div class="absolute -right-2 -bottom-2 text-3xl opacity-0 group-hover:opacity-10 transition pointer-events-none">🕸️</div><div class="w-8 h-8 md:w-10 md:h-10 p-1.5 md:p-2 flex items-center justify-center rounded-lg bg-slate-900 border z-10 flex-shrink-0" style="border-color:${RARITY[m.rarity].color}">${iconSvg}</div><div class="z-10 overflow-hidden"><p class="text-[10px] md:text-xs text-white font-bold truncate">${m.name}</p><p class="text-[8px] md:text-[9px] uppercase font-bold truncate" style="color:${RARITY[m.rarity].color}">${CAT_NAMES[t.k]} | ${RARITY[m.rarity].name}</p></div></div>`);}else{eqHtml.push(`<div class="flex items-center gap-2 md:gap-3 bg-slate-900/50 p-2 rounded-xl border border-slate-800 opacity-50" ondragover="allowDrop(event)" ondrop="dropEq(event, '${t.k}')"><div class="w-8 h-8 md:w-10 md:h-10 flex items-center justify-center rounded-lg bg-slate-900 border border-slate-700 flex-shrink-0 text-[10px] md:text-xs">❌</div><div class="overflow-hidden"><p class="text-[10px] md:text-xs text-slate-500 font-bold truncate">Стандарт</p><p class="text-[8px] md:text-[9px] uppercase font-bold text-slate-600 truncate">${t.n}</p></div></div>`);}});const ec=document.getElementById('equipped-slots-container');if(ec)ec.innerHTML=eqHtml.join('');if(document.getElementById('stat-hp')){document.getElementById('stat-hp').innerText=Math.round(MAX_HP*totalHp);document.getElementById('stat-speed').innerText=Math.round(totalSpeed*100)+'%';document.getElementById('stat-dmg').innerText=Math.round(totalDmg*100)+'%';document.getElementById('stat-rot').innerText=Math.round(totalRot*100)+'%';document.getElementById('bar-hp').style.width=Math.min(100,(totalHp/2)*100)+'%';document.getElementById('bar-speed').style.width=Math.min(100,(totalSpeed/2)*100)+'%';document.getElementById('bar-dmg').style.width=Math.min(100,(totalDmg/2)*100)+'%';document.getElementById('bar-rot').style.width=Math.min(100,(totalRot/2)*100)+'%';}const ic=document.getElementById('inv-count');if(ic)ic.innerText=myInventory.length;const invGrid=document.getElementById('inventory-grid');if(invGrid){invGrid.innerHTML='';for(let i=0;i<30;i++){if(i<myInventory.length){let modId=myInventory[i],mod=MODULES[modId];if(!mod)continue;let iconSvg=SVG_ICONS[mod.type](RARITY[mod.rarity].color);invGrid.innerHTML+=`<div class="inv-slot item-${mod.rarity} p-1.5 md:p-2 cursor-pointer md:cursor-grab md:active:cursor-grabbing hover:scale-105 transition" onclick="openCtxMenu(event, '${modId}', 'inv')" draggable="true" ondragstart="dragStartInv(event, '${modId}', ${i})" ondragover="allowDrop(event)" ondrop="dropInv(event, ${i})" title="${mod.name}">${iconSvg}</div>`;}else{invGrid.innerHTML+=`<div class="inv-slot empty border border-dashed border-slate-700 bg-slate-900/30 rounded-lg" ondragover="allowDrop(event)" ondrop="dropInv(event, ${i})"></div>`;}}}}
function spawnSpiders(x,y){for(let i=0;i<5;i++){let spider=document.createElement('div');spider.innerText='🕷';spider.className='scatter-spider';spider.style.left=x+'px';spider.style.top=y+'px';document.body.appendChild(spider);let angle=Math.random()*Math.PI*2,dist=100+Math.random()*150;setTimeout(()=>{spider.style.transform=`translate(${Math.cos(angle)*dist}px, ${Math.sin(angle)*dist}px) rotate(${Math.random()*360}deg)`;spider.style.opacity='0';},10);setTimeout(()=>spider.remove(),700);}}
let contextMode='inv',selectedEqSlot=null,selectedInvItem=null;
window.openCtxMenu=function(e,modId,mode='inv',slot=null){e.preventDefault();if(typeof playSound==='function')playSound('ui_click');selectedInvItem=modId;contextMode=mode;selectedEqSlot=slot;let cX=e.clientX,cY=e.clientY;if(e.touches&&e.touches.length>0){cX=e.touches[0].clientX;cY=e.touches[0].clientY;}spawnSpiders(cX,cY);let mod=MODULES[modId];const cn=document.getElementById('ctx-name');if(cn){cn.innerText=mod.name;cn.style.color=RARITY[mod.rarity].color;}const cc=document.getElementById('ctx-cat');if(cc){cc.innerText=`${CAT_NAMES[mod.type]} | ${RARITY[mod.rarity].name}`;cc.style.color=RARITY[mod.rarity].color;}let desc=[modStatsHtml(mod)];const cd=document.getElementById('ctx-desc');if(cd)cd.innerHTML=desc.join('<br>');const ce=document.getElementById('ctx-equip'),csell=document.getElementById('ctx-sell'),cdrop=document.getElementById('ctx-drop');if(mode==='inv'){if(ce)ce.innerText="Одягнути";if(csell){csell.style.display='block';csell.querySelector('span').innerText=`Продати ($${mod.price})`;}if(cdrop)cdrop.style.display='block';}else{if(ce)ce.innerText="Зняти";if(csell)csell.style.display='none';if(cdrop)cdrop.style.display='none';}const menu=document.getElementById('context-menu');if(!menu)return;menu.classList.remove('hidden');let mW=menu.offsetWidth||192,mH=menu.offsetHeight||150;if(cX+mW>window.innerWidth)cX-=mW;if(cY+mH>window.innerHeight)cY-=mH;menu.style.left=cX+'px';menu.style.top=cY+'px';};
document.addEventListener('click',(e)=>{const menu=document.getElementById('context-menu');if(menu&&!e.target.closest('.inv-slot')&&!e.target.closest('#equipped-slots-container')&&!e.target.closest('#context-menu'))menu.classList.add('hidden');});
const ctxEq=document.getElementById('ctx-equip');if(ctxEq)ctxEq.onclick=()=>{if(typeof playSound==='function')playSound('powerup');if(contextMode==='inv')socket.emit('equipModule',{id:selectedInvItem,type:MODULES[selectedInvItem].type});else socket.emit('unequipModule',{type:selectedEqSlot});document.getElementById('context-menu').classList.add('hidden');};
const ctxSell=document.getElementById('ctx-sell');if(ctxSell)ctxSell.onclick=()=>{if(typeof playSound==='function')playSound('ui_buy');socket.emit('sellModule',{id:selectedInvItem});document.getElementById('context-menu').classList.add('hidden');};
const ctxDrop=document.getElementById('ctx-drop');if(ctxDrop)ctxDrop.onclick=()=>{if(typeof playSound==='function')playSound('ui_click');socket.emit('dropModule',{id:selectedInvItem});document.getElementById('context-menu').classList.add('hidden');};

let hangarAnimId=null,hMouseX=150,hMouseY=150;const hCanvas=document.getElementById('hangar-canvas');let hCtx=hCanvas?hCanvas.getContext('2d'):null;
window.updateHangarMousePos=function(e){if(!hCanvas)return;const rect=hCanvas.getBoundingClientRect();let cx=e.clientX,cy=e.clientY;if(e.touches&&e.touches.length>0){cx=e.touches[0].clientX;cy=e.touches[0].clientY;}let scX=hCanvas.width/rect.width,scY=hCanvas.height/rect.height;hMouseX=(cx-rect.left)*scX;hMouseY=(cy-rect.top)*scY;};
if(hCanvas){hCanvas.addEventListener('mousemove',window.updateHangarMousePos);hCanvas.addEventListener('touchmove',window.updateHangarMousePos,{passive:true});}
window.startHangarPreview=function(){if(!hCanvas||!hCtx)return;if(hangarAnimId)cancelAnimationFrame(hangarAnimId);function drawPreview(){hCtx.clearRect(0,0,hCanvas.width,hCanvas.height);hCtx.save();hCtx.translate(150,150);let tAng=Math.atan2(hMouseY-150,hMouseX-150),cHex='#1e293b',hCol=myEquipped.hull?RARITY[MODULES[myEquipped.hull].rarity].color:'#0f172a',trCol=myEquipped.tracks?RARITY[MODULES[myEquipped.tracks].rarity].color:'#0f172a',cCol=myEquipped.cannon?RARITY[MODULES[myEquipped.cannon].rarity].color:'#0f172a',tuCol=myEquipped.turret?RARITY[MODULES[myEquipped.turret].rarity].color:'#334155';hCtx.fillStyle=trCol;hCtx.shadowColor=trCol;hCtx.shadowBlur=myEquipped.tracks?15:0;hCtx.fillRect(-36,-32,72,14);hCtx.fillRect(-36,18,72,14);hCtx.shadowBlur=0;hCtx.fillStyle=cHex;hCtx.strokeStyle=hCol;hCtx.lineWidth=myEquipped.hull?3:1;if(myEquipped.hull){hCtx.shadowColor=hCol;hCtx.shadowBlur=10;}hCtx.fillRect(-30,-22,60,44);hCtx.strokeRect(-30,-22,60,44);hCtx.shadowBlur=0;hCtx.save();hCtx.rotate(tAng);hCtx.fillStyle='#334155';hCtx.strokeStyle=cCol;hCtx.lineWidth=myEquipped.cannon?3:1;if(myEquipped.cannon){hCtx.shadowColor=cCol;hCtx.shadowBlur=10;}let cLen=45;if(myEquipped.cannon&&MODULES[myEquipped.cannon].stats.range>1.1)cLen=60;if(myEquipped.cannon&&MODULES[myEquipped.cannon].stats.range<1.0)cLen=35;hCtx.fillRect(0,-6,cLen,12);hCtx.strokeRect(0,-6,cLen,12);hCtx.shadowBlur=0;hCtx.fillStyle=cHex;hCtx.strokeStyle=tuCol;hCtx.lineWidth=myEquipped.turret?3:1;if(myEquipped.turret){hCtx.shadowColor=tuCol;hCtx.shadowBlur=15;}hCtx.beginPath();hCtx.arc(0,0,20,0,Math.PI*2);hCtx.fill();hCtx.stroke();hCtx.shadowBlur=0;hCtx.restore();hCtx.restore();hangarAnimId=requestAnimationFrame(drawPreview);}drawPreview();};
window.stopHangarPreview=function(){if(hangarAnimId)cancelAnimationFrame(hangarAnimId);};
window.updateLobbyUI=function(){if(!currentRoomData||currentRoomData.status==='playing')return;const lrn=document.getElementById('lobby-room-name');if(lrn)lrn.innerText=currentRoomData.hostName+" СЕСІЯ";const MAP_NAMES={'epic_map':'🌐 EPIC MAP','Бій Насмерть':'🔥 ДЕЗМАТЧ'};const modeNameStr=currentRoomData.mode==='survival'?'🧟 ':currentRoomData.mode==='prophunt'?'📦 ':currentRoomData.mode==='team_deathmatch'?'🤝 ':'⚔️ ';const vmn=document.getElementById('view-map-name');if(vmn)vmn.innerText=modeNameStr+(MAP_NAMES[currentRoomData.map]||currentRoomData.map);let winScoreText=currentRoomData.winScore;if(currentRoomData.mode==='survival')winScoreText='БЕЗКІНЕЧНО';if(currentRoomData.mode==='prophunt')winScoreText='ЧАС';if(currentRoomData.mode==='team_deathmatch')winScoreText=currentRoomData.tdmScore;const vws=document.getElementById('view-win-score');if(vws)vws.innerText=winScoreText;const isHost=(myId===currentRoomData.hostSocket);const hostPanel=document.getElementById('host-settings-panel');if(hostPanel){hostPanel.classList.toggle('hidden',!isHost);hostPanel.classList.toggle('flex',isHost);}if(isHost){document.querySelectorAll('.host-mode-select').forEach(el=>el.classList.toggle('selected',el.dataset.mode===currentRoomData.mode));document.querySelectorAll('.host-map-select').forEach(el=>el.classList.toggle('selected',el.dataset.map===currentRoomData.map));const maxPInput=document.getElementById('host-max-players');if(maxPInput&&document.activeElement!==maxPInput){maxPInput.value=currentRoomData.maxPlayers;const hmp=document.getElementById('host-max-players-val');if(hmp)hmp.innerText=currentRoomData.maxPlayers;}const winSInput=document.getElementById('host-win-score');if(winSInput&&document.activeElement!==winSInput)winSInput.value=currentRoomData.winScore;const scoreWrap=document.getElementById('host-score-wrap');if(scoreWrap)scoreWrap.style.display=currentRoomData.mode==='deathmatch'?'block':'none';const phWrap=document.getElementById('host-prophunt-wrap');if(phWrap){phWrap.style.display=currentRoomData.mode==='prophunt'?'block':'none';if(currentRoomData.mode==='prophunt'){const hht=document.getElementById('host-hide-time');if(hht)hht.value=currentRoomData.hideTime||30;const hst=document.getElementById('host-seek-time');if(hst)hst.value=currentRoomData.seekTime||120;let maxHuntersAllowed=Math.max(1,Object.keys(currentRoomData.players).length-1);let hInput=document.getElementById('host-hunter-count');if(hInput){hInput.max=maxHuntersAllowed;if(parseInt(hInput.value)>maxHuntersAllowed){hInput.value=maxHuntersAllowed;socket.emit('updateRoomSettings',{roomId:currentRoomId,hunterCount:maxHuntersAllowed});}hInput.value=currentRoomData.hunterCount||1;}}}const tdmWrap=document.getElementById('host-tdm-wrap');if(tdmWrap){tdmWrap.style.display=currentRoomData.mode==='team_deathmatch'?'block':'none';if(currentRoomData.mode==='team_deathmatch'){const htt=document.getElementById('host-tdm-teams');if(htt)htt.value=currentRoomData.tdmTeams||2;const htm=document.getElementById('host-tdm-time');if(htm)htm.value=currentRoomData.tdmTime||180;const hts=document.getElementById('host-tdm-score');if(hts)hts.value=currentRoomData.tdmScore||20;const htab=document.getElementById('host-tdm-autobalance');if(htab)htab.checked=currentRoomData.tdmAutoBalance;}}}const list=document.getElementById('players-list');if(!list)return;list.innerHTML='';const takenColors=new Set();const pKeys=Object.keys(currentRoomData.players);const lc=document.getElementById('lobby-count');if(lc)lc.innerText=`${pKeys.length} / ${currentRoomData.maxPlayers}`;const colorSelectors=document.getElementById('color-selectors');const teamSelectors=document.getElementById('team-selectors');const tdmTeamSelectors=document.getElementById('team-selectors-tdm');const ctt=document.getElementById('color-title-text');if(currentRoomData.mode==='prophunt'){if(colorSelectors)colorSelectors.classList.add('hidden');if(teamSelectors)teamSelectors.classList.remove('hidden');if(tdmTeamSelectors)tdmTeamSelectors.classList.add('hidden');if(ctt)ctt.innerText="Команда";}else if(currentRoomData.mode==='team_deathmatch'){if(colorSelectors)colorSelectors.classList.add('hidden');if(teamSelectors)teamSelectors.classList.add('hidden');if(tdmTeamSelectors){tdmTeamSelectors.classList.remove('hidden');tdmTeamSelectors.classList.add('grid');let aT=currentRoomData.tdmTeams||2;document.querySelectorAll('.tdm-team-btn').forEach((b,i)=>{b.style.display=i<aT?'block':'none';});}if(ctt)ctt.innerText="Команда";}else{if(colorSelectors)colorSelectors.classList.remove('hidden');if(teamSelectors)teamSelectors.classList.add('hidden');if(tdmTeamSelectors)tdmTeamSelectors.classList.add('hidden');if(ctt)ctt.innerText="Колір";}let myTeam=null;let currentHuntersCount=0;for(let id in currentRoomData.players){if(currentRoomData.players[id].team==='hunter')currentHuntersCount++;}for(let id in currentRoomData.players){const p=currentRoomData.players[id];if(p.color)takenColors.add(p.color);if(id===myId){myColor=p.color;isReady=p.ready;myTeam=p.team;}let visualColor='#475569';let visualText='';if(currentRoomData.mode==='prophunt'){if(p.team==='hunter'){visualColor='#ef4444';visualText='🔴 МИСЛИВЕЦЬ';}else if(p.team==='hider'){visualColor='#3b82f6';visualText='🔵 ХОВАЄТЬСЯ';}}else if(currentRoomData.mode==='team_deathmatch'){const tc={'red':'🔴 ЧЕРВОНІ','blue':'🔵 СИНІ','green':'🟢 ЗЕЛЕНІ','yellow':'🟡 ЖОВТІ'};const tcc={'red':'#ef4444','blue':'#3b82f6','green':'#22c55e','yellow':'#eab308'};if(p.team){visualColor=tcc[p.team];visualText=tc[p.team];}}else{visualColor=p.color?(p.color==='white'?'#f8fafc':p.color==='black'?'#1e293b':p.color==='red'?'#ef4444':p.color==='blue'?'#3b82f6':p.color==='brown'?'#78350f':'#9333ea'):'#475569';}const isLeader=(id===currentRoomData.hostSocket)?'👑':'';list.innerHTML+=`<div class="flex items-center justify-between p-3 md:p-4 bg-slate-900/50 rounded-xl border border-slate-700/50 mb-2 transition transform hover:scale-[1.02]"><div class="flex items-center gap-2 md:gap-3 overflow-hidden"><div class="w-4 h-4 md:w-6 md:h-6 rounded border border-slate-500 shadow-inner flex-shrink-0" style="background-color: ${visualColor}"></div><span class="font-bold text-white tracking-widest uppercase text-[10px] md:text-sm truncate">${p.name} ${isLeader} <span class="text-[8px] text-slate-400 ml-2">${visualText}</span></span></div><span class="text-[8px] md:text-xs font-bold px-2 py-1 md:px-3 md:py-1.5 rounded border ${p.ready?'bg-emerald-900/30 text-emerald-400 border-emerald-500/30':'bg-slate-800 text-slate-500 border-slate-700'} flex-shrink-0">${p.ready?'ГОТОВИЙ':'ЧЕКАЄ'}</span></div>`;}if(currentRoomData.mode==='prophunt'){document.querySelectorAll('.team-btn').forEach(btn=>{btn.classList.toggle('selected',btn.dataset.team===myTeam);if(btn.dataset.team==='hunter'&&currentHuntersCount>=(currentRoomData.hunterCount||1)&&myTeam!=='hunter'){btn.disabled=true;btn.classList.add('opacity-50','cursor-not-allowed');}else{btn.disabled=false;btn.classList.remove('opacity-50','cursor-not-allowed');}});}else if(currentRoomData.mode==='team_deathmatch'){document.querySelectorAll('.tdm-team-btn').forEach(btn=>{btn.classList.toggle('selected',btn.dataset.team===myTeam);});}else{document.querySelectorAll('.color-btn').forEach(btn=>{const c=btn.dataset.color;btn.classList.toggle('selected',c===myColor);btn.disabled=takenColors.has(c)&&c!==myColor;});}const btn=document.getElementById('btn-ready');if(!btn)return;const allReady=pKeys.every(id=>currentRoomData.players[id].ready);let canBeReady=(currentRoomData.mode==='prophunt'||currentRoomData.mode==='team_deathmatch')?!!myTeam:!!myColor;if(!canBeReady){btn.innerText=(currentRoomData.mode==='prophunt'||currentRoomData.mode==='team_deathmatch')?"ОБЕРІТЬ КОМАНДУ":"ОБЕРІТЬ КАМУФЛЯЖ";btn.disabled=true;btn.className="w-full py-4 md:py-6 rounded-xl md:rounded-2xl font-russo text-lg md:text-2xl uppercase tracking-widest bg-slate-800 text-slate-500 transition shadow-inner border border-slate-700 relative z-10";}else{btn.disabled=false;if(myId===currentRoomData.hostSocket){if(isReady){if(pKeys.length>=2&&allReady){btn.innerText="🚀 ЗАПУСК СЕСІЇ";btn.className="w-full py-4 md:py-6 rounded-xl md:rounded-2xl font-russo text-lg md:text-2xl uppercase tracking-widest bg-blue-600 hover:bg-blue-500 text-white transition shadow-[0_0_30px_rgba(37,99,235,0.6)] relative z-10";}else{btn.innerText="ГОТОВИЙ (ЧЕКАЄМО...)";btn.className="w-full py-4 md:py-6 rounded-xl md:rounded-2xl font-russo text-sm md:text-2xl uppercase tracking-widest bg-emerald-600 text-white transition shadow-[0_0_20px_rgba(16,185,129,0.4)] relative z-10";}}else{btn.innerText="ПІДТВЕРДИТИ";btn.className="w-full py-4 md:py-6 rounded-xl md:rounded-2xl font-russo text-lg md:text-2xl uppercase tracking-widest bg-slate-700 hover:bg-slate-600 text-white transition border border-slate-500 relative z-10";}}else{if(isReady){btn.innerText="ВІДМІНИТИ";btn.className="w-full py-4 md:py-6 rounded-xl md:rounded-2xl font-russo text-lg md:text-2xl uppercase tracking-widest bg-emerald-600 hover:bg-emerald-700 text-white transition shadow-[0_0_20px_rgba(16,185,129,0.4)] relative z-10";}else{btn.innerText="ПІДТВЕРДИТИ";btn.className="w-full py-4 md:py-6 rounded-xl md:rounded-2xl font-russo text-lg md:text-2xl uppercase tracking-widest bg-blue-600 hover:bg-blue-500 text-white transition shadow-[0_0_20px_rgba(37,99,235,0.4)] relative z-10";}}}};
