const htScore=document.getElementById('host-tdm-score');if(htScore)htScore.onchange=(e)=>socket.emit('updateRoomSettings',{roomId:currentRoomId,tdmScore:parseInt(e.target.value)});
const htAb=document.getElementById('host-tdm-autobalance');if(htAb)htAb.onchange=(e)=>socket.emit('updateRoomSettings',{roomId:currentRoomId,tdmAutoBalance:e.target.checked});const hHide=document.getElementById('host-hide-time');if(hHide)hHide.onchange=(e)=>socket.emit('updateRoomSettings',{roomId:currentRoomId,hideTime:parseInt(e.target.value)});const hSeek=document.getElementById('host-seek-time');if(hSeek)hSeek.onchange=(e)=>socket.emit('updateRoomSettings',{roomId:currentRoomId,seekTime:parseInt(e.target.value)});const hHunt=document.getElementById('host-hunter-count');if(hHunt)hHunt.onchange=(e)=>socket.emit('updateRoomSettings',{roomId:currentRoomId,hunterCount:parseInt(e.target.value)});
document.querySelectorAll('.color-btn').forEach(btn=>{btn.onclick=()=>{if(!btn.disabled){if(typeof playSound==='function')playSound('ui_click');socket.emit('setColor',{roomId:currentRoomId,color:btn.dataset.color});}}});
document.querySelectorAll('.team-btn').forEach(btn=>{btn.onclick=()=>{if(!btn.disabled){if(typeof playSound==='function')playSound('ui_click');socket.emit('setTeam',{roomId:currentRoomId,team:btn.dataset.team});}}});
const br=document.getElementById('btn-ready');if(br)br.onclick=()=>{if(typeof playSound==='function')playSound('ui_click');const pKeys=Object.keys(currentRoomData.players);const allReady=pKeys.every(id=>currentRoomData.players[id].ready);if(myId===currentRoomData.hostSocket&&isReady&&pKeys.length>=2&&allReady){socket.emit('startGame',currentRoomId);}else{socket.emit('toggleReady',currentRoomId);}};
const lrb=document.getElementById('leave-room-btn');if(lrb)lrb.onclick=()=>{if(typeof playSound==='function')playSound('ui_click');if(currentRoomId)socket.emit('leaveRoom',currentRoomId);currentRoomId=null;currentRoomData=null;showScreen('room-browser-screen');};
window.doCountdown=function(){showScreen('game-screen');const overlay=document.getElementById('countdown-overlay'),text=document.getElementById('countdown-text');if(overlay)overlay.classList.remove('hidden');bullets=[];particles=[];let count=3;if(text){text.innerText=count;text.className="text-[10rem] lg:text-[15rem] font-russo text-white drop-shadow-[0_0_50px_rgba(37,99,235,0.8)] scale-150 transition-transform";}const iv=setInterval(()=>{count--;if(count>0){if(text)text.innerText=count;if(typeof playSound==='function')playSound('ui_click');}else if(count===0){if(text){text.innerText="БІЙ!";text.classList.add('text-emerald-400','drop-shadow-[0_0_50px_rgba(16,185,129,0.8)]');}if(typeof playSound==='function')playSound('shoot');if(typeof startGameLoop==='function')startGameLoop();}else{clearInterval(iv);if(overlay)overlay.classList.add('hidden');}},1000);};
const btrl=document.getElementById('back-to-room-lobby-btn');if(btrl)btrl.onclick=()=>{if(typeof playSound==='function')playSound('ui_click');const wm=document.getElementById('winner-modal');if(wm)wm.classList.add('hidden');socket.emit('backToRoomLobby',currentRoomId);if(typeof switchMusicState==='function')switchMusicState('loby');showScreen('lobby-screen');};
window.showPropMenu=function(timeLeft){let propMenu=document.getElementById('prop-selection-menu');if(!propMenu){propMenu=document.createElement('div');propMenu.id='prop-selection-menu';propMenu.className='fixed inset-0 z-[100] flex flex-col items-center justify-center p-4 bg-black/90 backdrop-blur-md fade-in';const propsHtml=['prop_crate','prop_barrel','prop_sandbag','prop_rock','prop_bush','tree','prop_cone','prop_concrete','prop_hedgehog','prop_radar','prop_tent','prop_cont_red','prop_cont_blue','prop_fence_wood','prop_fence_metal','prop_wreck','prop_tires','prop_generator','prop_spotlight'].map(type=>{return`<div class="bg-slate-800 border-2 border-slate-600 rounded-xl p-2 cursor-pointer hover:border-blue-500 hover:scale-105 transition prop-card" data-proptype="${type}" onclick="selectPropType('${type}')"><canvas width="60" height="60" id="cvs_${type}"></canvas></div>`;}).join('');propMenu.innerHTML=`<h2 class="text-3xl font-russo text-white tracking-widest mb-2">ОБЕРІТЬ МАСКУВАННЯ</h2><p class="text-blue-400 font-bold mb-6">Залишилось: <span id="prop-timer-text" class="text-xl">${timeLeft}</span> сек</p><div class="grid grid-cols-4 sm:grid-cols-6 lg:grid-cols-8 gap-3 max-w-4xl max-h-[60vh] overflow-y-auto p-4 glass-panel rounded-3xl border border-slate-700">${propsHtml}</div>`;document.body.appendChild(propMenu);setTimeout(()=>{document.querySelectorAll('.prop-card').forEach(card=>{let pType=card.dataset.proptype,c=document.getElementById(`cvs_${pType}`);if(c){let ctx=c.getContext('2d');ctx.translate(30,30);if(typeof drPrp==='function')drPrp(ctx,{type:pType,x:-25,y:-25,w:50,h:50,r:25},0);}});},100);}else propMenu.classList.remove('hidden');let tl=timeLeft,timerInt=setInterval(()=>{tl--;let span=document.getElementById('prop-timer-text');if(span)span.innerText=tl;if(tl<=0){clearInterval(timerInt);let propMenuEl=document.getElementById('prop-selection-menu');if(propMenuEl&&!propMenuEl.classList.contains('hidden'))propMenuEl.classList.add('hidden');}},1000);};
window.selectPropType=function(type){if(typeof playSound==='function')playSound('ui_click');socket.emit('selectProp',{roomId:currentRoomId,type:type});const pm=document.getElementById('prop-selection-menu');if(pm)pm.classList.add('hidden');};

let upgSrcIdx=null,upgSrcId=null,upgTgtId=null,upgRollUnder=true;
window.renderUpgrader=function(){let m=document.getElementById('upg-my-inv'),s=document.getElementById('upg-sys-inv');if(!m||!s)return;m.innerHTML='';s.innerHTML='';myInventory.forEach((modId,i)=>{let mod=MODULES[modId];if(!mod)return;let icon=SVG_ICONS[mod.type](RARITY[mod.rarity].color);let sel=upgSrcIdx===i?'border-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.5)] scale-105':'border-slate-700 hover:border-slate-500';m.innerHTML+=`<div class="p-1.5 md:p-2 cursor-pointer bg-slate-900/50 rounded-xl border-2 transition ${sel} flex flex-col justify-between relative group" onclick="selectUpgSrc(${i},'${modId}')"><button onclick="event.stopPropagation(); openModuleInfo('${modId}')" class="absolute top-1 right-1 w-5 h-5 rounded-full bg-slate-800 text-slate-300 border border-slate-600 flex items-center justify-center text-[9px] font-russo hover:bg-blue-600 hover:text-white transition z-20" title="Характеристики">i</button><span class="text-[7px] md:text-[9px] font-bold text-white uppercase truncate text-center pr-4">${mod.name}</span><div class="my-1">${icon}</div><span class="text-[7px] md:text-[9px] font-bold text-emerald-400">$${mod.price}</span></div>`;});Object.keys(MODULES).forEach(modId=>{let mod=MODULES[modId];if(!mod)return;let icon=SVG_ICONS[mod.type](RARITY[mod.rarity].color);let sel=upgTgtId===modId?'border-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.5)] scale-105':'border-slate-700 hover:border-slate-500';s.innerHTML+=`<div class="p-1.5 md:p-2 cursor-pointer bg-slate-900/50 rounded-xl border-2 transition ${sel} flex flex-col justify-between relative group" onclick="selectUpgTgt('${modId}')"><button onclick="event.stopPropagation(); openModuleInfo('${modId}')" class="absolute top-1 right-1 w-5 h-5 rounded-full bg-slate-800 text-slate-300 border border-slate-600 flex items-center justify-center text-[9px] font-russo hover:bg-blue-600 hover:text-white transition z-20" title="Характеристики">i</button><span class="text-[7px] md:text-[9px] font-bold text-white uppercase truncate text-center pr-4">${mod.name}</span><div class="my-1">${icon}</div><span class="text-[7px] md:text-[9px] font-bold text-emerald-400">$${mod.price}</span></div>`;});updateUpgChance();};
window.openModuleInfo=function(modId){if(typeof playSound==='function')playSound('ui_click');let mod=MODULES[modId];if(!mod)return;let modal=document.getElementById('case-info-modal'),grid=document.getElementById('case-info-grid'),title=document.getElementById('case-info-title');if(!grid||!modal)return;grid.innerHTML='';title.innerText=mod.name.toUpperCase();title.style.color=RARITY[mod.rarity].color;let statsArr=modStatRows(mod).map(r=>({name:r.name,val:(r.pct>0?'+':'')+r.pct+'%',good:r.good}));let iconSvg=SVG_ICONS[mod.type](RARITY[mod.rarity].color);let contentHtml=`<div class="col-span-full flex flex-col items-center justify-center p-4 bg-slate-900/80 rounded-2xl border border-slate-700 mb-4"><div class="w-16 h-16 p-2 rounded-xl bg-slate-950 border mb-2 flex items-center justify-center" style="border-color:${RARITY[mod.rarity].color}">${iconSvg}</div><p class="text-sm font-russo" style="color:${RARITY[mod.rarity].color}">${RARITY[mod.rarity].name} | ${CAT_NAMES[mod.type]}</p><p class="text-xs text-slate-400 mt-1">Ціна: <span class="text-emerald-400 font-bold">$${mod.price}</span></p></div>`;statsArr.forEach(st=>{contentHtml+=`<div class="flex items-center justify-between bg-slate-800/60 p-3 rounded-xl border border-slate-700"><span class="text-xs text-slate-300 font-bold">${st.name}</span><span class="text-xs font-russo" style="color:${st.good?'#34d399':'#f87171'}">${st.val}</span></div>`;});grid.innerHTML=`<div class="col-span-full grid grid-cols-1 sm:grid-cols-2 gap-3">${contentHtml}</div>`;modal.classList.remove('hidden');};
window.selectUpgSrc=function(idx,id){if(typeof playSound==='function')playSound('ui_click');upgSrcIdx=idx;upgSrcId=id;let slot=document.getElementById('upg-slot-src');if(slot)slot.innerHTML=SVG_ICONS[MODULES[id].type](RARITY[MODULES[id].rarity].color);renderUpgrader();};
window.selectUpgTgt=function(id){if(typeof playSound==='function')playSound('ui_click');upgTgtId=id;let slot=document.getElementById('upg-slot-tgt');if(slot)slot.innerHTML=SVG_ICONS[MODULES[id].type](RARITY[MODULES[id].rarity].color);renderUpgrader();};
const bInp=document.getElementById('upg-bucks-add');if(bInp)bInp.addEventListener('input',updateUpgChance);
const upgToggleBtn=document.getElementById('upg-toggle-dir');if(upgToggleBtn)upgToggleBtn.onclick=()=>{if(typeof playSound==='function')playSound('ui_click');upgRollUnder=!upgRollUnder;upgToggleBtn.innerText=upgRollUnder?'Зона: ЗЛІВА':'Зона: СПРАВА';updateUpgChance();};
function updateUpgChance(){const bF=document.getElementById('upg-bar-fill'),cT=document.getElementById('upg-chance-txt'),btn=document.getElementById('upg-action-btn');if(!upgSrcId||!upgTgtId||!bF||!cT||!btn){if(btn)btn.disabled=true;return;}let sM=MODULES[upgSrcId],tM=MODULES[upgTgtId];let pIn=sM.price||5,pOut=tM.price||5;if(pIn>=pOut){cT.innerText="Помилка";cT.className="text-sm sm:text-lg lg:text-3xl font-russo text-red-500";bF.style.width='0%';btn.disabled=true;btn.innerText='НЕМОЖЛИВО';btn.className="w-full max-w-sm py-2 sm:py-3 lg:py-5 rounded-lg lg:rounded-xl font-russo text-[10px] sm:text-sm lg:text-2xl uppercase tracking-widest bg-red-900/50 text-red-400 border border-red-500 mt-auto";return;}let bAdd=parseInt(document.getElementById('upg-bucks-add').value)||0;let ch=Math.min(90,((pIn+bAdd)/pOut)*100);cT.innerText=ch.toFixed(1)+'%';cT.className="text-sm sm:text-lg lg:text-3xl font-russo text-emerald-400";bF.style.width=ch+'%';bF.className=`h-full bg-emerald-500 transition-all duration-300 relative ${upgRollUnder?'float-left':'float-right'}`;btn.disabled=false;btn.innerText='АПГРЕЙД!';btn.className="w-full max-w-sm py-2 sm:py-3 lg:py-5 rounded-lg lg:rounded-xl font-russo text-[10px] sm:text-sm lg:text-2xl uppercase tracking-widest bg-blue-600 hover:bg-blue-500 text-white transition shadow-[0_0_20px_rgba(37,99,235,0.4)] mt-auto";}
const upgBtn=document.getElementById('upg-action-btn');if(upgBtn)upgBtn.onclick=()=>{if(!upgSrcId||!upgTgtId)return;if(typeof playSound==='function')playSound('ui_click');let b=parseInt(document.getElementById('upg-bucks-add').value)||0;upgBtn.disabled=true;socket.emit('upgradeItem',{idx:upgSrcIdx,target:upgTgtId,bucks:b,rollUnder:upgRollUnder});};
const savedToken=localStorage.getItem('tankToken');if(savedToken&&typeof socket!=='undefined')socket.emit('authToken',savedToken);else showScreen('login-screen');